@extends('layout.app') @section('title','New Sales Order') @section('content')<div class="page-head"><div><span class="eyebrow">SALES</span><h1>New sales order</h1><p class="muted">Stock is checked and deducted atomically when the order is created.</p></div></div><div class="panel form-panel"><form method="POST" action="{{ route('orders.store') }}">@csrf<label>Customer<select name="customer_id"><option value="">Walk-in customer</option>@foreach($customers as $customer)<option value="{{ $customer->id }}">{{ $customer->name }} — {{ $customer->phone ?: $customer->email }}</option>@endforeach</select></label><label>Order date<input type="date" name="order_date" value="{{ old('order_date',now()->toDateString()) }}" required></label><label>Delivery address<textarea name="delivery_address" rows="3"></textarea></label><h2>Order items</h2><div id="items">@foreach($products as $i=>$product)<div class="order-line grid-3"><label>{{ $product->product_name }}<input type="hidden" name="items[{{ $i }}][product_id]" value="{{ $product->id }}"><small class="muted">Available: {{ $product->stock_quantity }} · UGX {{ number_format($product->product_price,2) }}</small></label><label>Quantity<input type="number" min="1" max="{{ $product->stock_quantity }}" name="items[{{ $i }}][quantity]" value="{{ $i===0 ? 1 : 0 }}"></label></div>@endforeach</div><div class="grid-2"><label>Discount<input type="number" min="0" step="0.01" name="discount_amount" value="0"></label><label>Tax<input type="number" min="0" step="0.01" name="tax_amount" value="0"></label></div><label>Notes<textarea name="notes" rows="3"></textarea></label><div class="form-actions"><a class="btn btn-light" href="{{ route('orders.index') }}">Cancel</a><button class="btn btn-primary">Create order</button></div></form></div>@endsection
